using System.Text;
using System.Text.Json;

namespace SevenWondersDuel.Engine;

/// <summary>
/// The Encoding manifest (spec A6, ADR 0003): the contract Python reads instead of encoding anything. It lists the
/// version, the sizes, every block with its offset and scaling, a name for every input and policy index, and the heads.
/// Generated by <c>7wd manifest [--version N]</c> and committed as data/encoding/v1.json and v2.json; a test fails when
/// the generated text differs from the committed file, so every Encoding change is a visible diff.
/// </summary>
public static class EncodingManifest
{
    /// <summary>Where the manifest of Encoding v1 lives, relative to the repository root.</summary>
    public static string RelativePath => EncodingVersion.V1.ManifestPath;

    /// <summary>Encoding v1's manifest.</summary>
    public static string Generate() => Generate(EncodingVersion.V1);

    /// <summary>A version's manifest as JSON text: 2-space indented, "\n" line endings, a final newline. Deterministic.</summary>
    public static string Generate(EncodingVersion encoding)
    {
        using var stream = new MemoryStream();
        using (var w = new Utf8JsonWriter(stream, new JsonWriterOptions
        {
            Indented = true,
            NewLine = "\n",
            // Plain ASCII text such as "<card>" stays readable; the file is never embedded in HTML.
            Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
        }))
        {
            w.WriteStartObject();
            w.WriteString("format", "7wd-encoding-manifest");
            w.WriteNumber("version", encoding.Number);
            w.WriteString("about",
                "Generated by `7wd manifest`; do not edit. C# is the only encoder: Python reads this file to size the "
                + "network and check shapes. Input values are float32, roughly 0-1, from the point of view of the player "
                + "to decide ('my' / 'opp'). Unknowns are zeros.");

            w.WriteStartObject("input");
            w.WriteNumber("size", encoding.InputSize);
            Blocks(w, encoding.InputBlocks);
            Names(w, encoding.InputNames);
            w.WriteEndObject();

            w.WriteStartObject("policy");
            w.WriteNumber("size", encoding.PolicySize);
            w.WriteString("masking", "illegal Moves are set to -inf before the softmax; the legal mask comes from C#");
            Blocks(w, encoding.PolicyBlocks);
            Names(w, encoding.PolicyNames);
            w.WriteEndObject();

            w.WriteStartObject("heads");
            w.WriteStartObject("policy");
            w.WriteNumber("size", encoding.PolicySize);
            w.WriteString("target", "Gumbel's improved policy (root visit shares in classic mode), over legal Moves");
            w.WriteEndObject();
            w.WriteStartObject("value");
            w.WriteNumber("size", 1);
            w.WriteString("activation", "tanh");
            w.WriteString("target", "final result for the player to decide: +1 win, 0 draw, -1 loss");
            w.WriteEndObject();
            w.WriteStartObject("outcome");
            w.WriteNumber("size", NetworkEncoding.OutcomeClasses.Length);
            w.WriteString("target", "the actual result's class, from the point of view of the player to decide");
            Names(w, NetworkEncoding.OutcomeClasses, "classes");
            w.WriteEndObject();
            w.WriteEndObject();

            w.WriteEndObject();
        }
        return Encoding.UTF8.GetString(stream.ToArray()) + "\n";
    }

    static void Blocks(Utf8JsonWriter w, EncodingBlock[] blocks)
    {
        w.WriteStartArray("blocks");
        foreach (var b in blocks)
        {
            w.WriteStartObject();
            w.WriteString("name", b.Name);
            w.WriteNumber("offset", b.Offset);
            w.WriteNumber("size", b.Size);
            w.WriteString("description", b.Description);
            w.WriteEndObject();
        }
        w.WriteEndArray();
    }

    static void Names(Utf8JsonWriter w, string[] names, string property = "names")
    {
        w.WriteStartArray(property);
        foreach (var n in names) w.WriteStringValue(n);
        w.WriteEndArray();
    }
}
